// Hide and Seek v4: original assets only. No director deck images are used here.
// Four generated images are textures on 3D planes. The other scenes are pure
// code visuals: a gold ring, floating wireframe boxes, and gold dust.
// One WebGL camera journey, smoothed in a single rAF loop. Scroll is only read,
// never written, in the loop. Text changes by opacity and transform only.
(function () {
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var loader = document.getElementById('loader');
  var fallback = document.getElementById('fallback');
  var labels = Array.prototype.slice.call(document.querySelectorAll('.label'));
  var sceneNum = document.getElementById('sceneNum');
  var progressFill = document.getElementById('progressFill');

  function showFallback() {
    document.body.classList.add('no-webgl');
    if (fallback) fallback.hidden = false;
    if (loader) loader.classList.add('done');
  }
  if (typeof THREE === 'undefined') { showFallback(); return; }

  // 7 stops. file = generated image plane. geo = code-only visual. none = dark dust void.
  var stops = [
    { file: 'data:image/webp;base64,', aspect: 1600 / 1066 },
    { geo: 'ring' },
    { file: 'data:image/webp;base64,', aspect: 1600 / 685 },
    { file: 'data:image/webp;base64,', aspect: 1600 / 1066 },
    { geo: 'boxes' },
    { file: 'data:image/webp;base64,', aspect: 1600 / 685 },
    { geo: 'none' }
  ];
  var spacing = 22;
  var startZ = 13;
  var animated = [];

  var canvas, renderer, scene, camera;
  try {
    canvas = document.getElementById('webgl');
    renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: false, powerPreference: 'high-performance' });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
    renderer.setSize(window.innerWidth, window.innerHeight);
    scene = new THREE.Scene();
    scene.fog = new THREE.Fog(0x050505, 18, 58);
    camera = new THREE.PerspectiveCamera(58, window.innerWidth / window.innerHeight, 0.1, 400);
  } catch (err) { showFallback(); return; }

  var manager = new THREE.LoadingManager();
  manager.onLoad = function () { if (loader) loader.classList.add('done'); };
  var textureLoader = new THREE.TextureLoader(manager);
  var goldWire = new THREE.MeshBasicMaterial({ color: 0xd4af37, wireframe: true, transparent: true, opacity: 0.7 });

  stops.forEach(function (stop, i) {
    var z = startZ - spacing - i * spacing;
    if (stop.file) {
      var texture = textureLoader.load(stop.file);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = 1;
      var w = 17, h = w / stop.aspect;
      var plane = new THREE.Mesh(
        new THREE.PlaneGeometry(w, h),
        new THREE.MeshBasicMaterial({ map: texture, fog: true })
      );
      plane.position.set(0, 0, z);
      scene.add(plane);
    } else if (stop.geo === 'ring') {
      var ring = new THREE.Mesh(new THREE.TorusGeometry(4.2, 0.06, 12, 80), goldWire);
      ring.position.set(0, 0, z);
      scene.add(ring); animated.push(ring);
    } else if (stop.geo === 'boxes') {
      [-3, 0, 3].forEach(function (x, j) {
        var box = new THREE.Mesh(new THREE.BoxGeometry(2.2, 2.2, 2.2), goldWire);
        box.position.set(x, (j - 1) * 1.4, z + (j - 1) * 2);
        scene.add(box); animated.push(box);
      });
    }
  });

  var dustCount = 350;
  var dustPos = new Float32Array(dustCount * 3);
  for (var d = 0; d < dustCount; d++) {
    dustPos[d * 3] = (Math.random() - 0.5) * 30;
    dustPos[d * 3 + 1] = (Math.random() - 0.5) * 16;
    dustPos[d * 3 + 2] = startZ - Math.random() * (stops.length * spacing);
  }
  var dustGeo = new THREE.BufferGeometry();
  dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3));
  var dust = new THREE.Points(dustGeo, new THREE.PointsMaterial({
    color: 0xd4af37, size: 0.06, transparent: true, opacity: 0.55,
    blending: THREE.AdditiveBlending, depthWrite: false
  }));
  scene.add(dust);

  var targetProgress = 0, smoothProgress = 0;
  var targetMouseX = 0, targetMouseY = 0, smoothMouseX = 0, smoothMouseY = 0;
  var activeScene = -1, lastProgressText = '';

  function readInputs() {
    var max = document.body.scrollHeight - window.innerHeight;
    targetProgress = max > 0 ? window.scrollY / max : 0;
  }
  window.addEventListener('scroll', readInputs, { passive: true });
  window.addEventListener('pointermove', function (e) {
    targetMouseX = (e.clientX / window.innerWidth - 0.5) * 2;
    targetMouseY = (e.clientY / window.innerHeight - 0.5) * 2;
  }, { passive: true });
  window.addEventListener('resize', function () {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  });

  function setScene(index) {
    if (index === activeScene) return;
    activeScene = index;
    labels.forEach(function (label, i) { label.classList.toggle('active', i === index); });
    var text = String(index + 1).padStart(2, '0');
    if (sceneNum && text !== lastProgressText) { sceneNum.textContent = text; lastProgressText = text; }
  }

  function frame() {
    requestAnimationFrame(frame);
    var ease = reduced ? 1 : 0.065;
    smoothProgress += (targetProgress - smoothProgress) * ease;
    smoothMouseX += (targetMouseX - smoothMouseX) * 0.05;
    smoothMouseY += (targetMouseY - smoothMouseY) * 0.05;
    var totalTravel = (stops.length - 1) * spacing;
    var camZ = startZ - smoothProgress * totalTravel;
    camera.position.set(smoothMouseX * 1.1, -smoothMouseY * 0.7, camZ);
    camera.lookAt(smoothMouseX * 0.6, 0, camZ - 20);
    if (!reduced) {
      dust.rotation.y += 0.0004;
      animated.forEach(function (obj, i) { obj.rotation.x += 0.003 + i * 0.0004; obj.rotation.y += 0.004; });
    }
    var nearest = Math.round((startZ - camZ - spacing) / spacing);
    if (nearest < 0) nearest = 0;
    if (nearest > stops.length - 1) nearest = stops.length - 1;
    setScene(nearest);
    if (progressFill) progressFill.style.transform = 'scaleX(' + smoothProgress.toFixed(4) + ')';
    renderer.render(scene, camera);
  }

  readInputs();
  setScene(0);
  frame();
  setTimeout(function () { if (loader) loader.classList.add('done'); }, 8000);
})();
